function spn1100_h($v): string{return htmlspecialchars((string)$v,ENT_QUOTES,'UTF-8');}
function spn1100_tid(): int {try{if(function_exists('tenant_id'))return (int)tenant_id();if(function_exists('current_tenant')){$t=current_tenant();return (int)($t['id']??0);}}catch(Throwable $e){}return 0;}
function spn1100_table(string $t): bool {static $c=[];if(isset($c[$t]))return $c[$t];if(!preg_match('/^[A-Za-z][A-Za-z0-9_]{0,63}$/',$t))return false;try{$q=db()->prepare('SELECT 1 FROM information_schema.TABLES WHERE TABLE_SCHEMA=DATABASE() AND TABLE_NAME=? LIMIT 1');$q->execute([$t]);return $c[$t]=(bool)$q->fetchColumn();}catch(Throwable $e){return $c[$t]=false;}}
function spn1100_key(string $s): string{return trim((string)preg_replace('/[^a-z0-9_-]+/','_',strtolower($s)),'_');}
function spn1100_path(string $u): string{$p=parse_url($u,PHP_URL_PATH);return rtrim((string)($p?:'/'),'/')?:'/';}
function spn1100_defaults(): array {return [
 ['nav_key'=>'businesses','label'=>'Businesses','url'=>'/businesses.php','group_key'=>'primary','parent_key'=>'','sort_order'=>10,'enabled'=>1,'priority'=>'primary'],
