function spn1100_manifest_items(): array {$out=[];$dir=__DIR__.'/public-nav-modules';foreach(glob($dir.'/*.json')?:[] as $file){$d=json_decode((string)@file_get_contents($file),true);if(!is_array($d))continue;$rows=isset($d['items'])&&is_array($d['items'])?$d['items']:[$d];foreach($rows as $r){if(!is_array($r)||empty($r['nav_key'])||empty($r['label'])||empty($r['url']))continue;$k=spn1100_key((string)$r['nav_key']);if(!$k)continue;$out[$k]=array_merge(['nav_key'=>$k,'group_key'=>'primary','parent_key'=>'','sort_order'=>100,'enabled'=>1,'priority'=>'secondary'],$r,['nav_key'=>$k,'source'=>'manifest']);}}return $out;}
function spn1100_overrides(int $tid): array {$o=[];if(spn1100_table('public_navigation_rules_v1100'))try{$q=db()->prepare('SELECT * FROM public_navigation_rules_v1100 WHERE tenant_id=?');$q->execute([$tid]);foreach($q->fetchAll()?:[] as $r)$o[(string)$r['nav_key']]=$r;}catch(Throwable $e){}elseif(spn1100_table('public_navigation_v1051'))try{$q=db()->prepare('SELECT * FROM public_navigation_v1051 WHERE tenant_id=?');$q->execute([$tid]);foreach($q->fetchAll()?:[] as $r)$o[(string)$r['nav_key']]=$r;}catch(Throwable $e){}return $o;}
function spn1100_items(?int $tenantId=null): array {$tid=$tenantId??spn1100_tid();$items=[];foreach(spn1100_defaults() as $r)$items[$r['nav_key']]=$r;foreach(spn1100_manifest_items() as $k=>$r)$items[$k]=array_merge($items[$k]??[],$r);foreach(spn1100_overrides($tid) as $k=>$r){$base=$items[$k]??['nav_key'=>$k,'label'=>$r['label']??$k,'url'=>$r['url']??'#','group_key'=>'primary','parent_key'=>'','sort_order'=>100,'enabled'=>1,'priority'=>'secondary'];foreach(['label','url','group_key','parent_key','priority'] as $f)if(isset($r[$f])&&$r[$f]!==null&&$r[$f]!=='')$base[$f]=(string)$r[$f];foreach(['sort_order','enabled'] as $f)if(isset($r[$f])&&$r[$f]!==null)$base[$f]=(int)$r[$f];$items[$k]=$base;}
 foreach($items as &$rr){if(function_exists('sk1301_canonical_url'))$rr['url']=sk1301_canonical_url((string)$rr['url']);}unset($rr);
 // Canonicalize duplicate URLs: one item wins; children of an alias follow the winner.
 $byPath=[];$aliases=[];foreach($items as $k=>$r){$p=spn1100_path((string)$r['url']);if(!isset($byPath[$p])){$byPath[$p]=$k;continue;}$winner=$byPath[$p];$a=$items[$winner];$scoreA=(empty($a['parent_key'])?100:0)+(1000-(int)$a['sort_order']);$scoreB=(empty($r['parent_key'])?100:0)+(1000-(int)$r['sort_order']);if($scoreB>$scoreA){$aliases[$winner]=$k;$byPath[$p]=$k;}else{$aliases[$k]=$winner;}}
 foreach($aliases as $from=>$to)unset($items[$from]);foreach($items as &$r)if(!empty($r['parent_key'])&&isset($aliases[$r['parent_key']]))$r['parent_key']=$aliases[$r['parent_key']];unset($r);
 $rows=array_values($items);usort($rows,fn($a,$b)=>[(string)$a['group_key'],(int)$a['sort_order'],(string)$a['label']]<=>[(string)$b['group_key'],(int)$b['sort_order'],(string)$b['label']]);return $rows;}
function spn1100_current(string $url): bool {$p=spn1100_path($url);$cur=spn1100_path((string)($_SERVER['REQUEST_URI']??'/'));return $p==='/'?$cur==='/':$cur===$p;}
function spn1100_tree(string $group='primary'): array {$rows=array_values(array_filter(spn1100_items(),fn($x)=>(int)$x['enabled']===1&&($x['group_key']===$group||($group==='primary'&&!empty($x['parent_key'])))));$by=[];foreach($rows as $x)$by[(string)$x['nav_key']]=$x;$children=[];foreach($rows as $x)if(!empty($x['parent_key']))$children[(string)$x['parent_key']][]=$x;$top=[];foreach($rows as $x)if(empty($x['parent_key'])&&$x['group_key']===$group){$x['_children']=$children[$x['nav_key']]??[];$top[]=$x;}return $top;}
function spn1100_render(string $group='primary'): void {foreach(spn1100_tree($group) as $r){$kids=$r['_children']??[];$active=spn1100_current((string)$r['url'])||array_filter($kids,fn($k)=>spn1100_current((string)$k['url']));?><div class="spn1100-item <?=$kids?'has-children':''?> <?=$active?'is-active':''?>"><a href="<?=spn1100_h($r['url'])?>" data-public-nav="<?=spn1100_h($r['nav_key'])?>"><?=spn1100_h($r['label'])?><?=$kids?'<span class="spn1100-caret">⌄</span>':''?></a><?php if($kids):?><div class="spn1100-dropdown"><?php foreach($kids as $k):?><a href="<?=spn1100_h($k['url'])?>" class="<?=spn1100_current((string)$k['url'])?'is-active':''?>"><?=spn1100_h($k['label'])?></a><?php endforeach;?></div><?php endif;?></div><?php }}
function spn1100_render_account(): void {foreach(spn1100_items() as $r)if((int)$r['enabled']===1&&$r['group_key']==='account'){?><a href="<?=spn1100_h($r['url'])?>"><?=spn1100_h($r['label'])?></a><?php }}
function spn1100_safe_url(string $url): bool {return str_starts_with($url,'/')||preg_match('#^https://#i',$url)===1;}
